-- Programações (escala 2º semestre 2026)
-- 1º semestre na planilha está só com o gabarito, sem eventos preenchidos.

SELECT e.id, t.title, t.sort_order FROM public.events e
CROSS JOIN (VALUES
  ('Levantar quantidade de pessoas', 1),
  ('Comprar ingredientes', 2),
  ('Preparar o alimento', 3),
  ('Decorar o local', 4),
  ('Servir', 5),
  ('Limpar e guardar', 6),
  ('Guardar nota fiscal e pedir reembolso', 7)
) AS t(title, sort_order);

